"""Generate the standalone FR-01–FR-14 customer design references."""

from pathlib import Path
import re

ROOT = Path(__file__).parent

JOURNEY = [
    ("Access", "sign-in.html"), ("Policies", "policies.html"),
    ("Request", "create-endorsement-request.html"), ("Evidence", "policy-evidence.html"),
    ("Assessment", "check-endorsement-eligibility.html"), ("Decision", "proposal-review.html"),
]
STAGE = {
    "sign-in.html": 0, "policies.html": 1, "policy-detail.html": 1,
    "policy-detail-coverage.html": 1, "create-endorsement-request.html": 2,
    "beneficiary-request-th.html": 2, "request-types-th.html": 2,
    "policy-evidence.html": 3, "check-endorsement-eligibility.html": 4,
    "proposal-review.html": 5, "change-history.html": 5,
}


def journey(filename, lang):
    if filename not in STAGE:
        return ""
    labels = ["เข้าสู่ระบบ", "กรมธรรม์", "คำขอ", "หลักฐาน", "การประเมิน", "การตัดสินใจ"] if lang == "th" else [item[0] for item in JOURNEY]
    items = []
    for number, ((_, target), label) in enumerate(zip(JOURNEY, labels), 1):
        current = ' aria-current="step"' if number - 1 == STAGE[filename] else ""
        items.append(f'<li><a href="{target}"{current}><span class="step-number">{number:02}</span><span>{label}</span></a></li>')
    name = "ขั้นตอนการทำรายการ" if lang == "th" else "Customer journey"
    return f'<nav class="journey" aria-label="{name}"><ol>{"".join(items)}</ol></nav>'


def page(filename, title, fr, body, lang="en"):
    document = f'''<!doctype html>
<html lang="{lang}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>{title} · I02 design</title><link rel="stylesheet" href="backlog.css"><script src="backlog.js" defer></script></head>
<body><a class="skip" href="#main">Skip to content</a><header class="top"><div class="top-inner"><a class="brand" href="index.html">Policy Endorsement Assistant<small>Synthetic customer design</small></a><nav class="nav" aria-label="Main"><a href="policies.html">Policies</a><a href="change-history.html">History</a><a href="index.html">All mockups</a><button type="button" data-signout>Sign out</button></nav></div></header>
{journey(filename, lang)}<main id="main" class="wrap"><p class="eyebrow">{fr} · Customer reference</p>{body}<footer class="footer">Illustrative synthetic data. This design cannot change a policy, issue coverage, or record a real decision.</footer></main></body></html>'''
    document = document.replace('<link rel="stylesheet" href="backlog.css">', '<link rel="stylesheet" href="backlog.css"><link rel="stylesheet" href="backlog-mobile.css">')
    document = document.replace('<body>', f'<body class="screen-{Path(filename).stem}">', 1)
    if filename == "sign-in.html":
        document = document.replace('</div><button class="button" type="submit">Sign in</button>', '</div><button class="secondary" type="button" id="toggle-password" aria-controls="password" aria-pressed="false">Show password</button><div class="actions"><button class="button" type="submit">Sign in</button></div>')
    if filename == "proposal-review.html":
        document = re.sub(
            r'(<div class="pair"><b>.*?</b>)<span>(.*?)</span><span>(.*?)</span></div>',
            r'\1<span><small class="pair-label">Current</small>\2</span><span><small class="pair-label">Proposed</small>\3</span></div>',
            document,
        )
    (ROOT / filename).write_text(document, encoding="utf-8")


index = '''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>I02 customer design index</title><link rel="stylesheet" href="backlog.css"></head><body><a class="skip" href="#main">Skip to content</a><header class="top"><div class="top-inner"><span class="brand">Policy Endorsement Assistant<small>UX mockups · FR-01–FR-14</small></span></div></header><main class="wrap" id="main"><p class="eyebrow">Customer journey</p><h1>Policy change design references</h1><p class="lede">Open each screen to review its layout and states. Every value and source below is synthetic. FR-12 and FR-13 verify this journey; they do not add customer screens.</p><ol class="index-list">
<li><a href="sign-in.html"><strong>1 · Sign in</strong><span>FR-01, FR-02 · demo account and ended session</span></a></li>
<li><a href="policies.html"><strong>2 · Owned policies</strong><span>FR-01, FR-02 · active, expired, and empty</span></a></li>
<li><a href="policy-detail.html"><strong>3 · Policy detail</strong><span>FR-02 · current facts and request entry</span></a></li>
<li><a href="create-endorsement-request.html"><strong>4 · Record a request</strong><span>FR-01, FR-03 · four change types and validation</span></a></li>
<li><a href="beneficiary-request-th.html"><strong>5 · คำขอเปลี่ยนผู้รับประโยชน์</strong><span>FR-01 · Thai beneficiary entry</span></a></li>
<li><a href="request-types-th.html"><strong>5b · คำขอเปลี่ยนแปลงอื่น</strong><span>FR-03 · Thai address, frequency, and rider labels</span></a></li>
<li><a href="policy-evidence.html"><strong>6 · Inspect evidence</strong><span>FR-04–FR-06 · wording, rule, and unresolved source</span></a></li>
<li><a href="check-endorsement-eligibility.html"><strong>7 · Assessment</strong><span>FR-05–FR-07 · three outcomes and failure</span></a></li>
<li><a href="proposal-review.html"><strong>8 · Proposal and decision</strong><span>FR-08–FR-10 · comparison, citations, confirmation, stale quote</span></a></li>
<li><a href="change-history.html"><strong>9 · Decision history</strong><span>FR-11 · recorded outcomes and UTC time</span></a></li>
<li><a href="policy-detail-coverage.html"><strong>10 · Expanded policy detail</strong><span>FR-14 · post-MVP coverage and exclusions</span></a></li></ol></main></body></html>'''
index = index.replace('</ol></main>', '<li><a href="shadcn-theme-preview.html"><strong>Shared theme preview</strong><span>Design tokens and component roles</span></a></li></ol></main>')
(ROOT / "index.html").write_text(index.replace('<link rel="stylesheet" href="backlog.css">', '<link rel="stylesheet" href="backlog.css"><link rel="stylesheet" href="backlog-mobile.css">'), encoding="utf-8")

