page("proposal-review.html", "Review a non-binding proposal", "FR-08 / FR-09 / FR-10", '''<a class="crumb" href="check-endorsement-eligibility.html">← Assessment</a><h1>Review a non-binding proposal</h1><p class="lede">Proposal PROP-DEMO-1001 · Payment frequency change · Life Protect Plus</p><div id="proposal-pending"><div class="note warning"><strong>Decision is non-binding</strong><p>Approval records your decision. It does not change your policy or coverage.</p></div><section class="panel"><h2>Current and proposed</h2><div class="pair pair-head"><b>Field</b><span>Current</span><span>Proposed</span></div><div class="pair"><b>Payment frequency</b><span>Monthly</span><span>Quarterly · changed</span></div><div class="pair"><b>Premium per period</b><span>THB 1,200.00 / month</span><span>THB 3,600.00 / quarter · changed</span></div><div class="pair"><b>Life cover</b><span>THB 1,000,000 · unchanged</span><span>THB 1,000,000 · unchanged</span></div><p class="hint">Values illustrate server-returned synthetic output. The browser does not calculate amounts.</p><p class="source-meta">Rating version RATE-2026.1 · Quote snapshot Q-DEMO-1001 · Exact validity awaits ticket refinement.</p></section><section class="panel"><h2>Why this can proceed</h2><p>Applicable policy wording and effective endorsement rule were verified.</p><ul class="list"><li><a href="policy-evidence.html">PW-LPP-01 · Section PAY-3 · v2026.1</a></li><li><a href="policy-evidence.html">RULE-FREQ-01 · Section 2.1 · v2026.1</a></li></ul></section><div class="actions"><button class="button" type="button" data-decide="approve">Approve proposal</button><button class="secondary" type="button" data-decide="reject">Reject proposal</button></div></div><div id="proposal-stale" class="note warning" hidden><h2>Proposal needs reassessment</h2><p>Its source or quote is no longer valid. No decision was recorded.</p><a class="button" href="check-endorsement-eligibility.html">Reassess request</a></div><div id="proposal-recorded" class="note success" tabindex="-1" hidden><h2>Decision recorded</h2><p id="decision-text">Your decision was recorded. Your policy and coverage remain unchanged.</p><a href="change-history.html">View decision history</a></div><dialog id="decision-dialog" aria-labelledby="dialog-title"><h2 id="dialog-title">Confirm decision</h2><p id="dialog-copy">Approval records your decision; it does not change policy or coverage.</p><div class="actions"><button class="button" type="button" id="confirm-decision">Record decision</button><button class="secondary" type="button" id="cancel-decision">Cancel</button></div></dialog><div class="preview"><strong>Review state</strong><div class="actions"><button class="secondary" type="button" data-proposal-state="pending">Pending</button><button class="secondary" type="button" data-proposal-state="stale">Stale quote</button></div></div>''')

page("change-history.html", "Decision history", "FR-11", '''<h1>Decision history</h1><p class="lede">These are your recorded decisions on synthetic proposals. Approval does not update a live policy or bind coverage.</p><div id="history-list"><article class="panel"><span class="badge">Approved decision</span><h2>Payment frequency proposal</h2><p>Proposed: Quarterly · THB 3,600.00 / quarter · Life cover unchanged</p><p class="source-meta">PROP-DEMO-1001 · Decision time: 2026-11-27 09:30 UTC</p><a href="proposal-review.html">View recorded proposal</a></article><article class="panel"><span class="badge neutral">Rejected decision</span><h2>Rider proposal</h2><p>Proposed: Add accidental-death rider · No policy change</p><p class="source-meta">PROP-DEMO-0998 · Decision time: 2026-11-20 08:15 UTC</p><a href="proposal-review.html">View proposal reference</a></article></div><div id="history-empty" class="panel" hidden><h2>No decisions recorded</h2><p>When you decide on a proposal, it will appear here.</p><a href="policies.html">View your policies</a></div><div class="preview"><strong>Review states</strong><div class="actions"><button class="secondary" data-history-state="list">Decisions</button><button class="secondary" data-history-state="empty">Empty history</button></div></div>''')

